import { cleanTypeDefinitions } from '../../src/orchestrator/dependencies'

describe('cleanTypeDefinitions', () => {
    describe('Function argument optionality', () => {
        test('makes function arguments optional', () => {
            const input = 'function foo(name: string, age: number): void {}'
            const result = cleanTypeDefinitions(input).serverDTs
            expect(result).toContain('name?: string')
            expect(result).toContain('age?: number')
        })

        test('preserves variable declarations', () => {
            const input = 'const myVar: string = "hello"'
            const result = cleanTypeDefinitions(input).serverDTs
            expect(result).toContain('const myVar: string')
        })

        test('preserves let declarations', () => {
            const input = 'let myVar: number = 42'
            const result = cleanTypeDefinitions(input).serverDTs
            expect(result).toContain('let myVar: number')
        })

        test('preserves var declarations', () => {
            const input = 'var myVar: boolean = true'
            const result = cleanTypeDefinitions(input).serverDTs
            expect(result).toContain('var myVar: boolean')
        })

        test('makes method parameters optional', () => {
            const input = 'class Test { method(param: string): void {} }'
            const result = cleanTypeDefinitions(input).serverDTs
            expect(result).toContain('param?: string')
        })
    })

    describe('Property names with dots', () => {
        test('quotes properties with dots when not already quoted', () => {
            const input = 'interface Test { user.name: string }'
            const result = cleanTypeDefinitions(input).serverDTs
            expect(result).toContain("'user.name'?:")
        })

        test('does not re-quote properties already quoted with single quotes', () => {
            const input = "interface Test { 'user.name': string }"
            const result = cleanTypeDefinitions(input).serverDTs
            // Should not become ''user.name''
            expect(result).toContain("'user.name'")
            expect(result).not.toContain("''user.name''")
        })

        test('does not re-quote properties already quoted with double quotes', () => {
            const input = 'interface Test { "user.name": string }'
            const result = cleanTypeDefinitions(input).serverDTs
            // Should preserve the double quote or convert consistently
            expect(result).not.toContain('\'"user.name"\'')
        })

        test('handles multiple dotted properties', () => {
            const input = 'interface Test { user.name: string; user.email: string }'
            const result = cleanTypeDefinitions(input).serverDTs
            expect(result).toContain("'user.name'?:")
            expect(result).toContain("'user.email'?:")
        })

        test('handles properties with multiple dots', () => {
            const input = 'interface Test { user.profile.name: string }'
            const result = cleanTypeDefinitions(input).serverDTs
            expect(result).toContain("'user.profile.name'?:")
        })
    })

    describe('Reserved word handling', () => {
        test('renames delete parameter', () => {
            const input = 'function foo(delete: boolean): void {}'
            const result = cleanTypeDefinitions(input).serverDTs
            expect(result).toContain('delete_?:')
            expect(result).not.toContain('delete?:')
        })

        test('renames function parameter', () => {
            const input = 'function foo(function: string): void {}'
            const result = cleanTypeDefinitions(input).serverDTs
            expect(result).toContain('function_?:')
            expect(result).not.toContain('function?:')
        })

        test('only renames reserved words as parameter names', () => {
            const input = 'function delete(): void {}'
            const result = cleanTypeDefinitions(input).serverDTs
            // Should preserve the function name
            expect(result).toContain('function delete')
        })

        test('handles both reserved words in same function', () => {
            const input = 'function foo(delete: boolean, function: string): void {}'
            const result = cleanTypeDefinitions(input).serverDTs
            expect(result).toContain('delete_?:')
            expect(result).toContain('function_?:')
        })
    })

    describe('Constructor handling', () => {
        test('removes static from constructor', () => {
            const input = 'class Test { static constructor() {} }'
            const result = cleanTypeDefinitions(input).serverDTs
            expect(result).toContain('constructor()')
            expect(result).not.toContain('static constructor')
        })

        test('removes static from constructor with space', () => {
            const input = 'class Test { static constructor () {} }'
            const result = cleanTypeDefinitions(input).serverDTs
            expect(result).toContain('constructor')
            expect(result).not.toContain('static constructor')
        })

        test('preserves normal static methods', () => {
            const input = 'class Test { static myMethod(): void {} }'
            const result = cleanTypeDefinitions(input).serverDTs
            expect(result).toContain('static myMethod')
        })
    })

    describe('Java type aliases', () => {
        test('adds ArrayList type alias', () => {
            const input = 'interface Test {}'
            const result = cleanTypeDefinitions(input).serverDTs
            expect(result).toContain('type ArrayList<T extends unknown = unknown> = T[]')
        })

        test('adds StringList type alias', () => {
            const input = 'interface Test {}'
            const result = cleanTypeDefinitions(input).serverDTs
            expect(result).toContain('type StringList = string[]')
        })

        test('adds List type alias', () => {
            const input = 'interface Test {}'
            const result = cleanTypeDefinitions(input).serverDTs
            expect(result).toContain('type List<T extends unknown = unknown> = T[]')
        })

        test('adds TimeZone type alias', () => {
            const input = 'interface Test {}'
            const result = cleanTypeDefinitions(input).serverDTs
            expect(result).toContain('type TimeZone = string')
        })

        test('aliases appear at the beginning', () => {
            const input = 'interface Test {}'
            const result = cleanTypeDefinitions(input).serverDTs
            const lines = result.split('\n')
            expect(lines[0]).toContain('ArrayList')
            expect(lines[1]).toContain('StringList')
            expect(lines[2]).toContain('List')
            expect(lines[3]).toContain('TimeZone')
        })
    })

    describe('Complex scenarios', () => {
        test('handles combination of transformations', () => {
            const input = `
class GlideRecord {
    static constructor() {}
    query(delete: string, user.name: string): void {}
    const table: string = "incident"
}
`
            const result = cleanTypeDefinitions(input).serverDTs

            // Check all transformations
            expect(result).toContain('constructor()')
            expect(result).not.toContain('static constructor')
            expect(result).toContain('delete_?:')
            expect(result).toContain("'user.name'?:")
            expect(result).toContain('const table: string')
        })

        test('preserves original content structure', () => {
            const input = `interface GlideSystem {
    info(message: string): void
    warn(message: string): void
}`
            const result = cleanTypeDefinitions(input).serverDTs

            expect(result).toContain('interface GlideSystem')
            expect(result).toContain('info')
            expect(result).toContain('warn')
        })

        test('handles empty input', () => {
            const input = ''
            const result = cleanTypeDefinitions(input).serverDTs

            // Should still have the type aliases
            expect(result).toContain('type ArrayList')
            expect(result).toContain('type StringList')
            expect(result).toContain('type List')
            expect(result).toContain('type TimeZone')
        })
    })

    describe('Edge cases', () => {
        test('handles properties ending with optional marker', () => {
            const input = 'interface Test { user.name?: string }'
            const result = cleanTypeDefinitions(input).serverDTs
            expect(result).toContain("'user.name'?:")
        })

        test('handles multiple occurrences of same reserved word', () => {
            const input = 'function foo(delete: string): void {} function bar(delete: number): void {}'
            const result = cleanTypeDefinitions(input).serverDTs
            const matches = (result.match(/delete_\?:/g) || []).length
            expect(matches).toBe(2)
        })

        test('handles properties with underscores and dots', () => {
            const input = 'interface Test { user_info.name: string }'
            const result = cleanTypeDefinitions(input).serverDTs
            expect(result).toContain("'user_info.name'?:")
        })

        test('handles properties with numbers and dots', () => {
            const input = 'interface Test { user1.name2: string }'
            const result = cleanTypeDefinitions(input).serverDTs
            expect(result).toContain("'user1.name2'?:")
        })
    })

    describe('Tables interface extraction', () => {
        test('extracts Tables interface into separate file', () => {
            const input = `
declare interface Tables {
    sn_test: sn_test
}
declare interface sn_test {
    field: string
}
declare interface OtherInterface {
    foo: string
}`
            const result = cleanTypeDefinitions(input)
            expect(result.tablesInterface).toEqual(`export {}

interface sn_test {
    field: string;
}

declare global {
interface Tables {
    sn_test: sn_test;
}
}
`)
            expect(result.serverDTs).toEqual(`/// <reference path="./tables.modules.d.ts" />

type ArrayList<T extends unknown = unknown> = T[];
type StringList = string[];
type List<T extends unknown = unknown> = T[];
type TimeZone = string;
declare interface OtherInterface {
    foo: string;
}
`)
        })

        test('adds triple-slash reference for extracted Tables interface', () => {
            const input = `declare interface Tables {
    sn_test: sn_test
}`
            const result = cleanTypeDefinitions(input)
            expect(result.serverDTs).toContain('/// <reference path="./tables.modules.d.ts" />')
        })

        test('does not add triple-slash reference when no Tables interface', () => {
            const input = `declare interface OtherInterface {
    foo: string
}`
            const result = cleanTypeDefinitions(input)
            expect(result.serverDTs).not.toContain('/// <reference path="./tables.modules.d.ts" />')
            expect(result.tablesInterface).toBeUndefined()
        })

        test('wraps extracted content in declare global', () => {
            const input = `declare interface Tables {
    incident: GlideRecord
}`
            const result = cleanTypeDefinitions(input)
            expect(result.tablesInterface).toContain('declare global')
            expect(result.tablesInterface).not.toContain('declare interface')
        })

        test('handles Tables interface with nested braces', () => {
            const input = `declare interface Tables {
    sn_test1: { name: string; value: number }
    sn_test2: sn_test2
}`
            const result = cleanTypeDefinitions(input)
            expect(result.tablesInterface).toContain('sn_test1: {')
            expect(result.tablesInterface).toContain('name: string')
            expect(result.tablesInterface).toContain('value: number')
            expect(result.tablesInterface).toContain('sn_test2: sn_test2')
        })

        test('handles empty Tables interface', () => {
            const input = `declare interface Tables {
}`
            const result = cleanTypeDefinitions(input)
            expect(result.tablesInterface).not.toBeNull()
            expect(result.tablesInterface).toContain('interface Tables')
            expect(result.tablesInterface).toContain('declare global')
        })

        test('extracts referenced type from inline definitions', () => {
            const input = `declare interface sn_test { test: string } declare interface Tables { sn_test: sn_test }`
            const result = cleanTypeDefinitions(input)
            expect(result.tablesInterface).not.toBeNull()
            expect(result.tablesInterface).toContain('interface sn_test')
            expect(result.tablesInterface).toContain('interface Tables')
            expect(result.tablesInterface).toContain('declare global')
            expect(result.serverDTs).not.toContain('interface sn_test')
            expect(result.serverDTs).not.toContain('interface Tables')
        })

        test('extracts base interfaces when table interface extends another', () => {
            const input = `declare interface sn_base { a: string } declare interface sn_extended extends sn_base { b: string } declare interface Tables { sn_extended: sn_extended }`
            const result = cleanTypeDefinitions(input)
            expect(result.tablesInterface).not.toBeNull()
            expect(result.tablesInterface).toContain('interface sn_extended')
            expect(result.tablesInterface).toContain('interface sn_base')
            expect(result.serverDTs).not.toContain('interface sn_extended')
            expect(result.serverDTs).not.toContain('interface sn_base')
        })

        test('handles braces in single-line comments', () => {
            const input = `declare interface Tables {
    // This comment has a brace } in it
    sn_test: sn_test
}
declare interface OtherInterface { foo: string }`
            const result = cleanTypeDefinitions(input)
            expect(result.tablesInterface).not.toBeNull()
            expect(result.tablesInterface).toContain('// This comment has a brace } in it')
            expect(result.tablesInterface).toContain('sn_test: sn_test')
            expect(result.serverDTs).toContain('declare interface OtherInterface')
            expect(result.serverDTs).not.toContain('interface Tables')
        })

        test('handles braces in block comments', () => {
            const input = `declare interface Tables {
    /* This comment has a brace } in it */
    sn_test: sn_test
}
declare interface OtherInterface { foo: string }`
            const result = cleanTypeDefinitions(input)
            expect(result.tablesInterface).not.toBeNull()
            expect(result.tablesInterface).toContain('/* This comment has a brace } in it */')
            expect(result.tablesInterface).toContain('sn_test: sn_test')
            expect(result.serverDTs).toContain('declare interface OtherInterface')
            expect(result.serverDTs).not.toContain('interface Tables')
        })

        test('handles braces in string literals', () => {
            const input = `declare interface Tables {
    sn_test: "not a brace }"
}
declare interface OtherInterface { foo: string }`
            const result = cleanTypeDefinitions(input)
            expect(result.tablesInterface).not.toBeNull()
            expect(result.tablesInterface).toContain('sn_test: "not a brace }"')
            expect(result.serverDTs).toContain('declare interface OtherInterface')
            expect(result.serverDTs).not.toContain('interface Tables')
        })
    })
})
